const TAN=19, GREY=72;
// ---- base plate ring (layout A: N/S long, W/E short) ----
fill(-8,-8,16,2,GREY,{kit:'plates'});
fill(-8,6,16,2,GREY,{kit:'plates'});
fill(-10,-4,2,8,GREY,{kit:'plates'});
fill(8,-4,2,8,GREY,{kit:'plates'});
[[-10,-6],[8,-6],[-10,4],[8,4]].forEach(c=>put('3022',GREY,c[0],c[1]));

const skN=[[-5,-8,2,2],[-1,-8,2,2],[3,-8,2,2]];
const skS=[[-5,6,2,2],[-1,6,2,2],[3,6,2,2]];
const skW=[[-10,-3,2,2],[-10,1,2,2]];
const skE=[[8,-3,2,2],[8,1,2,2]];

// ---- lower arcade courses 0 and 1 ----
for(let c=0;c<2;c++){
  const B = (c%2==0); // layout B on course 0
  if(B){
    fill(-6,-8,12,2,TAN,{kit:'bricks',skip:skN});
    fill(-6,6,12,2,TAN,{kit:'bricks',skip:skS});
    fill(-10,-6,2,12,TAN,{kit:'bricks',skip:skW});
    fill(8,-6,2,12,TAN,{kit:'bricks',skip:skE});
    [[-8,-8],[6,-8],[-8,6],[6,6]].forEach(k=>put('3003',TAN,k[0],k[1]));
  } else {
    fill(-8,-8,16,2,TAN,{kit:'bricks',skip:skN});
    fill(-8,6,16,2,TAN,{kit:'bricks',skip:skS});
    fill(-10,-4,2,8,TAN,{kit:'bricks',skip:skW});
    fill(8,-4,2,8,TAN,{kit:'bricks',skip:skE});
    [[-10,-6],[8,-6],[-10,4],[8,4]].forEach(k=>put('3003',TAN,k[0],k[1]));
  }
}
log('parts now '+count());

const TAN=19, DT=28;
