[[-10,-6],[8,-6],[-10,4],[8,4]].forEach(k=>put('3003',TAN,k[0],k[1]));
log('parts '+count());

const TAN=19, DT=28;
const skN=[[-5,-7,1,1],[-2,-7,1,1],[1,-7,1,1],[4,-7,1,1]];
const skS=[[-5,6,1,1],[-2,6,1,1],[1,6,1,1],[4,6,1,1]];
const skW=[[-9,-3,1,1],[-9,2,1,1]];
const skE=[[8,-3,1,1],[8,2,1,1]];
const corners=[[-9,-6],[-8,-7],[8,-6],[7,-7],[-9,5],[-8,6],[8,5],[7,6]];
for(let c=0;c<3;c++){
  const open = c<2;
  fill(-7,-7,14,1,TAN,{kit:'bricks',bond:c%2,skip:open?skN:[]});
  fill(-7,6,14,1,TAN,{kit:'bricks',bond:c%2,skip:open?skS:[]});
  fill(-9,-5,1,10,TAN,{kit:'bricks',bond:c%2,skip:open?skW:[]});
  fill(8,-5,1,10,TAN,{kit:'bricks',bond:c%2,skip:open?skE:[]});
  corners.forEach(k=>put('3005',TAN,k[0],k[1]));
}
// cornice tiles
fill(-7,-7,14,1,DT,{kit:'tiles'});
fill(-7,6,14,1,DT,{kit:'tiles'});
fill(-9,-5,1,10,DT,{kit:'tiles'});
fill(8,-5,1,10,DT,{kit:'tiles'});
corners.forEach(k=>put('3070b',DT,k[0],k[1]));
log('parts '+count());
